from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log, log_info
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.vm import extract_all_archives_from_path
from taf.rfrl.procedures.resources.python.parser.btslog_parser import is_entry_in_log_file


def general_siso_auto_cloud_verification_of_up_fragmentation_dl_ul(testing_env: TestingEnv):
    """
    Based on:
    QC Test ID: 1245
    QC Test Name: General_SiSo_Auto_Verification_of_UP_fragmentation_DL_UL

    Should report to:
    QC Test ID: 48117
    QC Test Name: General_Siso_Auto_Cloud_Verification_of_UP_Fragmentation_DL_UL

    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors
    snapshot_dir_path = testing_env.downloads_dir_path
    params_initial_state = {}
    testing_env.variables.set(name='params_initial_state', value=params_initial_state)

    for du in bts.dus:
        try:
            _store_initial_params_values(du, params_initial_state)
            _set_required_params_values(du)
            _reset_du_to_refresh_snapshot_content(du)
            snapshot_file_path = _collect_snapshot(du, snapshot_dir_path)
            _check_syslog_file_content_in_snapshot(du, snapshot_file_path, errors)
        except ResultError as exc:
            errors.add_from_exception(exc)

    errors.check()


def teardown_for_general_siso_auto_cloud_verification_of_up_fragmentation_dl_ul(testing_env: TestingEnv):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]
    params_initial_state = testing_env.variables.get(name='params_initial_state')

    for du in bts.dus:
        du.config.set_many(params_values=params_initial_state[du.name])
        du.check_state(state='on_air')


def _store_initial_params_values(du, params_initial_state):
    params_values = []
    params_initial_state[du.name] = params_values

    for cell in du.cells:
        params_values.append({'dist_name': cell.config_dist_name,
                              'param': 'pucchModeSelect',
                              'value': du.config.get(dist_name=cell.config_dist_name,
                                                     param='pucchModeSelect')})

    params_values.append({'dist_name': 'MRBTS-{}/NRBTS-{}',
                          'param': 'actFdmScheduling',
                          'value': du.config.get(dist_name='MRBTS-{}/NRBTS-{}',
                                                 param='actFdmScheduling')})
    params_values.append({'dist_name': 'MRBTS-{}/NRBTS-{}',
                          'param': 'actFdmEnhancedScheduling',
                          'value': du.config.get(dist_name='MRBTS-{}/NRBTS-{}',
                                                 param='actFdmEnhancedScheduling')})


def _set_required_params_values(du):
    params_values = []

    for cell in du.cells:
        params_values.append({'dist_name': cell.config_dist_name,
                              'param': 'pucchModeSelect',
                              'value': 'longPucch'})

    params_values.append({'dist_name': 'MRBTS-{}/NRBTS-{}',
                          'param': 'actFdmScheduling',
                          'value': 'true'})
    params_values.append({'dist_name': 'MRBTS-{}/NRBTS-{}',
                          'param': 'actFdmEnhancedScheduling',
                          'value': 'true'})

    du.config.set_many(params_values=params_values)
    du.check_state(state='on_air')


def _reset_du_to_refresh_snapshot_content(du):
    du.allow_alarm(fault_id='4592',
                   fault_name='BTS Reset Cause')
    du.cu.allow_alarm(fault_id='7104',
                      fault_name='Matching ServedCell not found over F1-C')
    du.reset_and_wait_for_on_air()
    du.cu.check_inactive_alarm(fault_id='7104',
                               fault_name='Matching ServedCell not found over F1-C',
                               timeout=120)
    du.disallow_alarm(fault_id='4592',
                      fault_name='BTS Reset Cause')
    du.cu.disallow_alarm(fault_id='7104',
                         fault_name='Matching ServedCell not found over F1-C')


def _collect_snapshot(du, snapshot_dir_path):
    return du.collect_snapshot(path=snapshot_dir_path)


@pretty_log
def _check_syslog_file_content_in_snapshot(du, snapshot_file_path, errors):
    log_info(f'Extracting snapshot from {du.name}', to_console=True)
    syslog_file_path = rf'{snapshot_file_path}/rcplog_[0-9]*\.zip/symptomreport/log_data/logs\.zip/syslog_latest_[0-9]*\.zip/syslog_[0-9]*'
    extracted_syslog_file_path = extract_all_archives_from_path(regex_path=syslog_file_path)
    log_info(f'Checking whether syslog file from {du.name} snapshot contains expected entries', to_console=True)

    for cell in du.cells:
        missing_syslog_entries = _get_missing_syslog_entries_for_cell(extracted_syslog_file_path, cell)

        if missing_syslog_entries:
            errors.add(error_type='SyslogContent', error_msg=f'Expected entries {missing_syslog_entries} for cell {cell.name} not found '
                                                             f'in syslog file {extracted_syslog_file_path} extracted from snapshot')


def _get_missing_syslog_entries_for_cell(syslog_file_path, cell):
    missing_syslog_entries = []
    expected_syslog_entries = ['ulPrbMuting:1',
                               'prbMuting: 1',
                               f'nrCellIdentity:{cell.nr_cell_identity} Fragmentation enabled [Ul] = 1',
                               f'nrCellIdentity:{cell.nr_cell_identity} Fragmentation enabled [Dl] = 1']

    for expected_syslog_entry in expected_syslog_entries:
        log_info(f'Checking whether syslog file {syslog_file_path} contains "{expected_syslog_entry}" entry for {cell.name} cell')
        if not is_entry_in_log_file(entry=expected_syslog_entry,
                                    log_file_path=syslog_file_path):
            missing_syslog_entries.append(expected_syslog_entry)

    return missing_syslog_entries
